SELECT
id, username, nick_name, email, mobile, gender, avatar, status, create_time, update_time, last_login_time
FROM
sys_user

    
        AND username LIKE CONCAT('%', #{username}, '%')
    
    
        AND nick_name LIKE CONCAT('%', #{nickName}, '%')
    
    
        AND gender = #{gender}
    
    
        AND status = #{status}
    
    
        
            
                AND create_time >= #{startTime}
            
            
                AND create_time <= #{endTime}
            
            
                AND create_time BETWEEN #{startTime} AND #{endTime}
            
        
    
    AND is_deleted = 0


    ORDER BY ${orderByColumn} ${isAsc == 'asc' ? 'ASC' : 'DESC'}


    ORDER BY create_time DESC

SELECT *
FROM sys_user

    
        github_id = #{providerId}
    
    
        wechat_id = #{providerId}
    
    AND is_deleted = 0
